package com.chengyinhub.business.service.support;

import com.chengyinhub.business.domain.*;
import com.chengyinhub.business.domain.dto.AuditReviewDTO;
import com.chengyinhub.business.mapper.*;
import com.chengyinhub.business.service.impl.AuditTaskServiceImpl;
import com.chengyinhub.business.service.support.*;
import java.lang.reflect.Proxy;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.AopTestUtils;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

/** Real AuditTask state/record/journal transactions and W18 locking SQL; CMS status writes remain explicit local fixture edges. */
class LegacyCmsTemplateApproval40cTest {
    LegacyCmsApproval40cFixture fixture;AnnotationConfigApplicationContext context;JdbcTemplate db;AuditTaskServiceImpl audits;TopicBundleReviewService bundle;LegacyCmsTemplateApprovalBoundary guard;
    @BeforeEach void setup()throws Exception{fixture=new LegacyCmsApproval40cFixture();fixture.setup();context=(AnnotationConfigApplicationContext)ReflectionTestUtils.getField(fixture,"context");db=(JdbcTemplate)ReflectionTestUtils.getField(fixture,"db");audits=(AuditTaskServiceImpl)ReflectionTestUtils.getField(fixture,"audits");bundle=(TopicBundleReviewService)ReflectionTestUtils.getField(fixture,"bundle");guard=context.getBean(LegacyCmsTemplateApprovalBoundary.class);}
    @AfterEach void close(){if(fixture!=null)fixture.close();}
    CmsMemberTemplate template(){CmsMemberTemplate t=new CmsMemberTemplate();t.setId(501L);t.setMemberId(7L);t.setTitle("Fixture protected template");t.setDelFlag(0);t.setDraftStatus(1);t.setStatus(0L);t.setCheckStatus(0);t.setPublishStatus(0L);return t;}
    AuditReviewDTO decision(int status,String key){AuditReviewDTO r=new AuditReviewDTO();r.setStatus(status);r.setExpectedVersion(0);r.setRequestId(key);r.setActorRoleCode("SYNTHETIC_REVIEWER");if(status==2)r.setReasonText("Fixture rejection");return r;}
    long topicTask(){return ReflectionTestUtils.invokeMethod(fixture,"submit");}
    void marker(String value){db.update("update cms_member_template set w18_provenance_kind=? where id=501",value);}
    void assertUntouched(long task){assertEquals(0,db.queryForObject("select status from audit_task where id=?",Integer.class,task));assertEquals(0,db.queryForObject("select version from audit_task where id=?",Integer.class,task));assertEquals(0,db.queryForObject("select count(*) from audit_record where action='APPROVE'",Integer.class));assertEquals(0,db.queryForObject("select count(*) from business_audit_event",Integer.class));assertEquals(0,db.queryForObject("select count(*) from fixture_side_effect",Integer.class));}
    @SuppressWarnings("unchecked") <T>T proxy(Class<T> type,java.lang.reflect.InvocationHandler h){return (T)Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},h);}
    long personalTask(boolean library)throws Exception{
        CmsMemberTemplate t=template();CmsTemplateLibrary projection=new CmsTemplateLibrary();projection.setId(701L);projection.setMemberTemplateId(501L);projection.setMemberId(7L);projection.setDelFlag(0);projection.setStatus(0L);projection.setPublishStatus(0L);projection.setTitle("Fixture public projection");if(library){t.setStatus(1L);t.setCheckStatus(1);}
        CmsMemberTemplateMapper templates=proxy(CmsMemberTemplateMapper.class,(p,m,a)->{switch(m.getName()){case "selectCmsMemberTemplateByIdsForUpdate":return Collections.singletonList(t);case "selectCmsMemberTemplateById":return t;case "applyAuditDecision":db.update("insert into fixture_side_effect(kind) values('template-state')");db.update("update cms_member_template set status=? where id=501",((CmsMemberTemplate)a[0]).getStatus());return 1;default:throw new AssertionError(m.getName());}});
        CmsTemplateLibraryMapper projections=proxy(CmsTemplateLibraryMapper.class,(p,m,a)->{switch(m.getName()){case "selectByMemberTemplateForUpdate":return library?Collections.singletonList(projection):Collections.emptyList();case "selectCmsTemplateLibraryById":return projection;case "applyAuditDecision":db.update("insert into fixture_side_effect(kind) values('library-state')");return 1;default:throw new AssertionError(m.getName());}});
        Object target=AopTestUtils.getUltimateTargetObject(audits);ReflectionTestUtils.setField(target,"templateMapper",templates);ReflectionTestUtils.setField(target,"libraryMapper",projections);
        return library?audits.submitOrRefreshTemplateLibrary(701L,7L,TemplateAuditSnapshot.market(projection)):audits.submitOrRefreshTemplate(501L,7L,TemplateAuditSnapshot.personal(t));
    }
    @Test void ordinaryPersonalTemplateAndLibraryPositiveControlsStillApprove()throws Exception{
        long personal=personalTask(false);assertEquals(1,audits.review(personal,900L,decision(1,"legacy-personal")));assertEquals(1,db.queryForObject("select status from audit_task where id=?",Integer.class,personal));
        long library=personalTask(true);assertEquals(1,audits.review(library,900L,decision(1,"legacy-library")));assertEquals(1,db.queryForObject("select status from audit_task where id=?",Integer.class,library));
    }
    @Test void nonNullMarkerBlocksPersonalApprovalBeforeTaskCAS()throws Exception{long task=personalTask(false);marker("W18_MANAGED");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"protected-personal")));assertUntouched(task);}
    @Test void nullMarkerWithSidecarBlocksActualLibraryApproval()throws Exception{long task=personalTask(true);db.update("insert into w18_cms_template_provenance values(501)");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"protected-library")));assertUntouched(task);}
    @Test void emptyUnknownAndWhitespaceMarkersBlockActualTopicBundle(){long task=topicTask();for(String marker:Arrays.asList("","FUTURE_KIND"," ","\t")){marker(marker);assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"protected-topic-"+marker.length()+marker.hashCode())));assertUntouched(task);}}
    @Test void nullMarkerSidecarCannotRideBundledTopicApproval(){long task=topicTask();db.update("insert into w18_cms_template_provenance values(501)");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"sidecar-topic")));assertUntouched(task);}
    @Test void markerWithoutSidecarStillBlocksTopicApproval(){long task=topicTask();marker("W18_MANAGED");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"marker-topic")));assertUntouched(task);}
    @Test void missingCanonicalTemplateAndSchemaFailureNeverBecomeLegacy(){long task=topicTask();db.update("delete from cms_member_template where id=501");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"missing-topic-template")));assertUntouched(task);db.update("insert into cms_member_template(id) values(501)");db.execute("drop table w18_cms_template_provenance");assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"missing-schema")));assertUntouched(task);}
    @Test void missingBoundaryBeanCannotApproveEitherSharedPath()throws Exception{long task=personalTask(false);ReflectionTestUtils.setField((Object)AopTestUtils.getUltimateTargetObject(audits),"legacyTemplateApprovalBoundary",null);IllegalStateException e=assertThrows(IllegalStateException.class,()->audits.review(task,900L,decision(1,"missing-personal-provider")));assertEquals("LEGACY_TEMPLATE_APPROVAL_GUARD_UNAVAILABLE",e.getMessage());assertUntouched(task);long topic=topicTask();ReflectionTestUtils.setField(bundle,"legacyTemplateApprovalBoundary",null);assertThrows(RuntimeException.class,()->audits.review(topic,900L,decision(1,"missing-topic-provider")));assertUntouched(topic);}
    @Test void protectedSourceCanStillBeRejectedWithoutInventingUsageRights(){long task=topicTask();marker("W18_MANAGED");assertEquals(1,audits.review(task,900L,decision(2,"protected-reject")));assertEquals(2,db.queryForObject("select status from audit_task where id=?",Integer.class,task));assertEquals(0,db.queryForObject("select count(*) from audit_record where action='APPROVE'",Integer.class));assertEquals("W18_MANAGED",db.queryForObject("select w18_provenance_kind from cms_member_template where id=501",String.class));}
    @Test void boundaryRequiresWritableSameTransactionEvenOnDirectInvocation()throws Exception{assertThrows(RuntimeException.class,()->guard.requireGenericApprovalAllowed(template()));LegacyCmsTemplateApprovalBoundary direct=AopTestUtils.getUltimateTargetObject(guard);assertThrows(RuntimeException.class,()->direct.requireGenericApprovalAllowed(template()));TransactionTemplate tx=new TransactionTemplate(context.getBean(PlatformTransactionManager.class));tx.setReadOnly(true);assertThrows(RuntimeException.class,()->tx.execute(s->{guard.requireGenericApprovalAllowed(template());return null;}));}
    @Test void secondLockReadObservesNewSidecarInSameTransactionInsteadOfCachedLegacyState(){TransactionTemplate tx=new TransactionTemplate(context.getBean(PlatformTransactionManager.class));assertThrows(RuntimeException.class,()->tx.execute(s->{guard.requireGenericApprovalAllowed(template());db.update("insert into w18_cms_template_provenance values(501)");guard.requireGenericApprovalAllowed(template());return null;}));assertEquals(0,db.queryForObject("select count(*) from w18_cms_template_provenance",Integer.class));}
    @Test void entireLockedTemplateBatchIsCheckedBeforeFirstBundledDraftWrite()throws Exception{
        CmsTopicMapper topics=(CmsTopicMapper)ReflectionTestUtils.getField(bundle,"topicMapper");CmsTopicChapterMapper chapters=(CmsTopicChapterMapper)ReflectionTestUtils.getField(bundle,"chapterMapper");CmsTopicNodeMapper originalNodes=(CmsTopicNodeMapper)ReflectionTestUtils.getField(bundle,"nodeMapper");CmsMemberTemplateMapper originalTemplates=(CmsMemberTemplateMapper)ReflectionTestUtils.getField(bundle,"templateMapper");
        com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper();CmsTopicNode firstNode=originalNodes.selectCmsTopicNodeList(new CmsTopicNode()).get(0);CmsTopicNode secondNode=json.readValue(json.writeValueAsString(firstNode),CmsTopicNode.class);secondNode.setId(firstNode.getId()+1);secondNode.setTemplateId(502L);secondNode.setSortId(2L);
        CmsTopicChapter chapter=chapters.selectCmsTopicChapterList(new CmsTopicChapter()).get(0);com.fasterxml.jackson.databind.node.ArrayNode blocks=(com.fasterxml.jackson.databind.node.ArrayNode)json.readTree(chapter.getBlocksJson());blocks.addObject().put("type","node").put("nodeId",secondNode.getId());chapter.setBlocksJson(json.writeValueAsString(blocks));
        CmsMemberTemplate first=originalTemplates.selectCmsMemberTemplateById(501L);first.setDraftStatus(0);first.setStatus(0L);first.setCheckStatus(0);first.setPublishStatus(0L);CmsMemberTemplate second=json.readValue(json.writeValueAsString(first),CmsMemberTemplate.class);second.setId(502L);db.update("insert into cms_member_template(id,w18_provenance_kind) values(502,'W18_MANAGED')");java.util.concurrent.atomic.AtomicInteger writes=new java.util.concurrent.atomic.AtomicInteger();
        CmsTopicNodeMapper nodes=proxy(CmsTopicNodeMapper.class,(p,m,a)->{if(m.getName().equals("selectCmsTopicNodeList")||m.getName().equals("selectByTopicForUpdate"))return Arrays.asList(firstNode,secondNode);throw new AssertionError(m.getName());});
        CmsMemberTemplateMapper templates=proxy(CmsMemberTemplateMapper.class,(p,m,a)->{if(m.getName().equals("selectCmsMemberTemplateById"))return Long.valueOf(501).equals(a[0])?first:second;if(m.getName().equals("selectCmsMemberTemplateByIdsForUpdate"))return Arrays.asList(first,second);if(m.getName().equals("approveBundledDraft")){writes.incrementAndGet();db.update("update cms_member_template set status=1 where id=?",a[0]);return 1;}throw new AssertionError(m.getName());});
        TopicBundleReviewService complete=new TopicBundleReviewService(topics,chapters,nodes,templates);ReflectionTestUtils.setField(complete,"legacyTemplateApprovalBoundary",guard);ReflectionTestUtils.setField((Object)AopTestUtils.getUltimateTargetObject(audits),"topicBundleReviewService",complete);String raw=complete.freezeForSubmission(101L,7L).getSnapshotJson();long task=audits.submitOrRefreshTopicBundle(101L,7L,raw);
        assertThrows(RuntimeException.class,()->audits.review(task,900L,decision(1,"batch-denial")));assertEquals(0,writes.get());assertEquals(0,db.queryForObject("select count(*) from cms_member_template where status=1",Integer.class));assertUntouched(task);
        // Positive control for the identical two-draft fixture: both truly legacy rows may still be approved.
        db.update("update cms_member_template set w18_provenance_kind=null where id=502");assertEquals(1,audits.review(task,900L,decision(1,"batch-legacy-control")));assertEquals(2,writes.get());assertEquals(2,db.queryForObject("select count(*) from cms_member_template where status=1",Integer.class));
    }

    @Test void currentMasterSupplyGateStillBlocksAutoOnlineAfterLegacyApproval(){long task=topicTask();fixture.supplyBlockReason="fixture unavailable supply";assertEquals(1,audits.review(task,900L,decision(1,"supply-gate")));assertEquals(1,db.queryForObject("select status from audit_task where id=?",Integer.class,task));assertEquals(Integer.valueOf(0),fixture.lastUserStatus);assertEquals(Boolean.FALSE,fixture.lastVisibility);assertEquals(1,db.queryForObject("select count(*) from fixture_side_effect where kind='publishApprovedRouteSnapshot'",Integer.class));}

}
